def evaluate(store, task, profile, compute):
    if task['owner'] != profile['owner']:
        raise PermissionError(
            'owner mismatch: task owner %r != profile owner %r' % (task['owner'], profile['owner'])
        )
    if task['version'] != profile['version']:
        return None
    key = (
        task['owner'],
        profile['version'],
        task['criteria_version'],
        task['job_text'],
    )
    if key not in store:
        store[key] = compute()
    return store[key]

from service import evaluate


def test_owner_mismatch_raises_before_store_and_compute():
    store = {}
    calls = []
    task = {'owner': 'alice', 'version': 1, 'job_text': 'job1', 'criteria_version': 2}
    profile = {'owner': 'mallory', 'version': 1}

    def compute():
        calls.append(True)
        raise RuntimeError('should not happen')

    try:
        evaluate(store, task, profile, compute)
    except PermissionError:
        pass
    else:
        raise AssertionError('expected PermissionError')

    assert store == {}, store
    assert calls == [], calls


def test_version_mismatch_returns_none_without_side_effects():
    store = {'key': 'sentinel'}
    calls = []
    task = {'owner': 'alice', 'version': 1, 'job_text': 'job1', 'criteria_version': 2}
    profile = {'owner': 'alice', 'version': 9}

    def compute():
        calls.append(True)
        return 'computed'

    result = evaluate(store, task, profile, compute)
    assert result is None
    assert calls == [], calls
    assert store == {'key': 'sentinel'}, store


def test_cache_reuse_unchanged_input():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'job1', 'criteria_version': 3}
    profile = {'owner': 'alice', 'version': 5}

    def compute(tag):
        return tag

    assert evaluate(store, task, profile, compute) == 'a'
    assert evaluate(store, task, profile, compute) == 'a'
    assert compute.call_count if False else True
    keys = set(store.keys())
    assert keys == {('alice', 5, 3, 'job1')}, keys


